#!/usr/bin/env bash
# karsin terminal setup — tmux + zsh + iTerm2 environment
#
# Generated by build_setup.py from karsinkk's live configs (2026-06-04).
# What it installs:
#   - tmux (Homebrew) with a C-a prefix config, TPM + 9 plugins,
#     10 switchable themes (prefix+T), status-bar styles (prefix+B)
#   - tmux-restore: session snapshot/restore for claude/codex agent panes
#     (launchd agents + a Claude Code SessionStart hook — see README)
#   - zsh aliases: t / ta / tls / tcc / tcca + iTerm2 shell integration
#   - FiraCode Nerd Font + an iTerm2 dynamic profile (font + colors only)
#
# Flags (env vars):
#   TERMSETUP_EXTRACT_ONLY=1      write embedded files and exit
#                                 (no brew/git/launchctl/network)
#   TERMSETUP_SKIP_TMUX_RESTORE=1 skip the tmux-restore daemon + Claude hook
#
# Idempotent: re-running is safe. Existing files are backed up as *.bak.<ts>.
set -euo pipefail

EXTRACT_ONLY="${TERMSETUP_EXTRACT_ONLY:-0}"
SKIP_TMUX_RESTORE="${TERMSETUP_SKIP_TMUX_RESTORE:-0}"

say()  { printf '\033[1;34m[setup]\033[0m %s\n' "$*"; }
warn() { printf '\033[1;33m[setup:warn]\033[0m %s\n' "$*"; }

if [ "$(uname -s)" != "Darwin" ]; then
  warn "this script targets macOS (iTerm2, launchd, Homebrew casks)"
  [ "$EXTRACT_ONLY" = "1" ] || exit 1
fi

backup() {
  if [ -e "$1" ] && [ ! -L "$1" ]; then
    cp -p "$1" "$1.bak.$(date +%s)"
    say "backed up $1"
  fi
}

# ---------------------------------------------------------------------------
# Phase A: write all embedded files (pure file writes, no network)
# ---------------------------------------------------------------------------
say "writing config files"
mkdir -p "$HOME/.config/tmux/themes" "$HOME/.config/tmux/scripts" \
         "$HOME/projects/tmux-restore/hooks" \
         "$HOME/Library/Application Support/iTerm2/DynamicProfiles" \
         "$HOME/.local/bin"

backup "$HOME/.config/tmux/tmux.conf"
cat > "$HOME/.config/tmux/tmux.conf" <<'EOF_KTS_1'
# Based on https://github.com/karsinkk/Config-Files/blob/master/.tmux.conf

# Behavior
set -g mouse on
set -g history-limit 3000
set -g default-terminal "tmux-256color"
set -ga terminal-overrides ",xterm-256color:RGB"
set -ga terminal-overrides ",xterm-kitty:RGB"
set -g set-clipboard on

bind y setw synchronize-panes

# Prefix: C-a
unbind C-b
set-option -g prefix C-a
bind-key C-a send-prefix

# Panes and windows
bind | split-window -h
bind - split-window -v
unbind '"'
unbind %
unbind &
bind-key q kill-pane
bind -n C-Left select-pane -L
bind -n C-Right select-pane -R
bind -n C-Up select-pane -U
bind -n C-Down select-pane -D
bind -n M-Left select-pane -L
bind -n M-Right select-pane -R
bind -n M-Up select-pane -U
bind -n M-Down select-pane -D
bind -n S-Left previous-window
bind -n S-Right next-window
set -g pane-border-lines heavy
bind r source-file ~/.tmux.conf \; display-message "tmux config reloaded: #{@karsin_tmux_theme}"
bind T display-menu -T "#[align=centre]tmux theme" -x C -y C \
  "Dracula local" d "set -g @karsin_tmux_theme dracula-local \; source-file ~/.tmux.conf \; display-message 'theme: dracula-local'" \
  "Bright local" b "set -g @karsin_tmux_theme bright \; source-file ~/.tmux.conf \; display-message 'theme: bright'" \
  "Dark local" k "set -g @karsin_tmux_theme dark \; source-file ~/.tmux.conf \; display-message 'theme: dark'" \
  "" \
  "Official Dracula" D "set -g @karsin_tmux_theme public-dracula \; source-file ~/.tmux.conf \; display-message 'theme: official dracula'" \
  "Catppuccin Mocha" c "set -g @karsin_tmux_theme public-catppuccin-mocha \; source-file ~/.tmux.conf \; display-message 'theme: catppuccin mocha'" \
  "Catppuccin Latte" l "set -g @karsin_tmux_theme public-catppuccin-latte \; source-file ~/.tmux.conf \; display-message 'theme: catppuccin latte'" \
  "Tokyo Night local" t "set -g @karsin_tmux_theme tokyo-local \; source-file ~/.tmux.conf \; display-message 'theme: tokyo-local'" \
  "PowerKit Tokyo Night" P "set -g @karsin_tmux_theme public-powerkit-tokyo \; source-file ~/.tmux.conf" \
  "Ukiyo Kanagawa" u "set -g @karsin_tmux_theme public-ukiyo-kanagawa \; source-file ~/.tmux.conf \; display-message 'theme: ukiyo kanagawa'" \
  "Ukiyo OneDark" o "set -g @karsin_tmux_theme public-ukiyo-onedark \; source-file ~/.tmux.conf \; display-message 'theme: ukiyo onedark'"
bind B display-menu -T "#[align=centre]tmux bar" -x C -y C \
  "Online rounded" o "set -g @karsin_tmux_bar_style online-rounded \; source-file ~/.tmux.conf \; display-message 'bar: online rounded'" \
  "Dracula pro" d "set -g @karsin_tmux_bar_style dracula-pro \; source-file ~/.tmux.conf \; display-message 'bar: dracula pro'" \
  "Dracula compact" c "set -g @karsin_tmux_bar_style dracula-compact \; source-file ~/.tmux.conf \; display-message 'bar: dracula compact'" \
  "Emoji powerline" e "set -g @karsin_tmux_bar_style emoji-powerline \; source-file ~/.tmux.conf \; display-message 'bar: emoji powerline'" \
  "Full telemetry" f "set -g @karsin_tmux_bar_style full \; source-file ~/.tmux.conf \; display-message 'bar: full telemetry'" \
  "Plain text" p "set -g @karsin_tmux_bar_style plain \; source-file ~/.tmux.conf \; display-message 'bar: plain text'"
bind E display-menu -T "#[align=centre]tmux emoji" -x C -y C \
  "Preset: terminal" t "set -g @karsin_tmux_icon_session '⌘' \; set -g @karsin_tmux_icon_cpu '⚙' \; set -g @karsin_tmux_icon_gpu 'G' \; set -g @karsin_tmux_icon_ram '▣' \; set -g @karsin_tmux_icon_network '⇅' \; set -g @karsin_tmux_icon_weather '☁' \; set -g @karsin_tmux_icon_time '◷' \; source-file ~/.tmux.conf \; display-message 'emoji preset: terminal'" \
  "Preset: clean emoji" e "set -g @karsin_tmux_icon_session '💻' \; set -g @karsin_tmux_icon_cpu '⚙' \; set -g @karsin_tmux_icon_gpu '🎮' \; set -g @karsin_tmux_icon_ram '💾' \; set -g @karsin_tmux_icon_network '📶' \; set -g @karsin_tmux_icon_weather '☁' \; set -g @karsin_tmux_icon_time '◷' \; source-file ~/.tmux.conf \; display-message 'emoji preset: clean'" \
  "Preset: nerd font" n "set -g @karsin_tmux_icon_session '' \; set -g @karsin_tmux_icon_cpu '' \; set -g @karsin_tmux_icon_gpu '󰢮' \; set -g @karsin_tmux_icon_ram '' \; set -g @karsin_tmux_icon_network '󰈀' \; set -g @karsin_tmux_icon_weather '󰖕' \; set -g @karsin_tmux_icon_time '󰥔' \; source-file ~/.tmux.conf \; display-message 'emoji preset: nerd font'" \
  "" \
  "Set session icon" s "command-prompt -p 'session icon' \"set -g @karsin_tmux_icon_session '%%' \; source-file ~/.tmux.conf\"" \
  "Set CPU icon" c "command-prompt -p 'CPU icon' \"set -g @karsin_tmux_icon_cpu '%%' \; source-file ~/.tmux.conf\"" \
  "Set GPU icon" g "command-prompt -p 'GPU icon' \"set -g @karsin_tmux_icon_gpu '%%' \; source-file ~/.tmux.conf\"" \
  "Set RAM icon" r "command-prompt -p 'RAM icon' \"set -g @karsin_tmux_icon_ram '%%' \; source-file ~/.tmux.conf\"" \
  "Set network icon" n "command-prompt -p 'network icon' \"set -g @karsin_tmux_icon_network '%%' \; source-file ~/.tmux.conf\"" \
  "Set weather icon" w "command-prompt -p 'weather icon' \"set -g @karsin_tmux_icon_weather '%%' \; source-file ~/.tmux.conf\"" \
  "Set time icon" t "command-prompt -p 'time icon' \"set -g @karsin_tmux_icon_time '%%' \; source-file ~/.tmux.conf\""

# Quiet alerts
set-option -g visual-activity off
set-option -g visual-bell off
set-option -g visual-silence off
set-window-option -g monitor-activity off
set-option -g bell-action none

# Theme
# Change this with prefix + T.
set -gqo @karsin_tmux_theme "dracula-local"
# Change this with prefix + B.
set -gqo @karsin_tmux_bar_style "online-rounded"
# Optional weather location for the emoji bar. Empty means wttr.in auto-location.
set -gqo @karsin_tmux_weather_location ""
# Change these with prefix + E.
set -gqo @karsin_tmux_icon_session ""
set -gqo @karsin_tmux_icon_cpu ""
set -gqo @karsin_tmux_icon_gpu "󰢮"
set -gqo @karsin_tmux_icon_ram ""
set -gqo @karsin_tmux_icon_network "󰈀"
set -gqo @karsin_tmux_icon_weather "󰖕"
set -gqo @karsin_tmux_icon_time "󰥔"

set -g status-position bottom
set -g status-justify left
set -g status-interval 5
set -g status-left-length 40
set -g status-right-length 180

if -F '#{==:#{@karsin_tmux_theme},dark}' 'source-file ~/.config/tmux/themes/dark.tmux'
if -F '#{==:#{@karsin_tmux_theme},bright}' 'source-file ~/.config/tmux/themes/bright.tmux'
if -F '#{==:#{@karsin_tmux_theme},dracula-local}' 'source-file ~/.config/tmux/themes/dracula-local.tmux'
if -F '#{==:#{@karsin_tmux_theme},tokyo-local}' 'source-file ~/.config/tmux/themes/tokyo-local.tmux'
if -F '#{==:#{@karsin_tmux_theme},public-dracula}' 'source-file ~/.config/tmux/themes/public-dracula.tmux'
if -F '#{==:#{@karsin_tmux_theme},public-catppuccin-mocha}' 'source-file ~/.config/tmux/themes/public-catppuccin-mocha.tmux'
if -F '#{==:#{@karsin_tmux_theme},public-catppuccin-latte}' 'source-file ~/.config/tmux/themes/public-catppuccin-latte.tmux'
if -F '#{==:#{@karsin_tmux_theme},public-powerkit-tokyo}' 'source-file ~/.config/tmux/themes/public-powerkit-tokyo.tmux'
if -F '#{==:#{@karsin_tmux_theme},public-ukiyo-kanagawa}' 'source-file ~/.config/tmux/themes/public-ukiyo-kanagawa.tmux'
if -F '#{==:#{@karsin_tmux_theme},public-ukiyo-onedark}' 'source-file ~/.config/tmux/themes/public-ukiyo-onedark.tmux'

# tmux-resurrect
set -g @resurrect-save-bash-history 'on'

# Plugins
set -g @plugin 'tmux-plugins/tpm'
set -g @plugin 'tmux-plugins/tmux-sensible'
set -g @plugin 'tmux-plugins/tmux-resurrect'
set -g @plugin 'tmux-plugins/tmux-continuum'
set -g @plugin 'tmux-plugins/tmux-battery'
set -g @plugin 'tmux-plugins/tmux-cpu'
set -g @plugin 'tmux-plugins/tmux-net-speed'
set -g @plugin 'tmux-plugins/tmux-sidebar'
set -g @plugin 'tmux-plugins/tmux-yank'

# Public themes are cloned under ~/.config/tmux/plugins and selectable with prefix + T.
# set -g @plugin 'dracula/tmux'
# set -g @plugin 'catppuccin/tmux#v2.3.0'
# set -g @plugin 'fabioluciano/tmux-powerkit'
# set -g @plugin 'Nybkox/tmux-ukiyo'

run '~/.config/tmux/plugins/tpm/tpm'
EOF_KTS_1

cat > "$HOME/.config/tmux/themes/bright.tmux" <<'EOF_KTS_2'
# Bright, high-contrast theme for dim terminal profiles.

set -g status-style "fg=#111827,bg=#f8fafc,bold"
set -g status-left "#[fg=#ffffff,bg=#2563eb,bold] #S #[fg=#2563eb,bg=#f8fafc,nobold] "
set -g status-right "#[fg=#111827,bg=#f8fafc,bold] CPU:#{cpu_percentage} #[fg=#475569,bg=#f8fafc,nobold]|#[fg=#111827,bg=#f8fafc,bold] Batt: #{battery_icon} #{battery_percentage} #{battery_remain} #[fg=#ffffff,bg=#0f766e,bold] %d/%m #[fg=#ffffff,bg=#dc2626,bold] %H:%M:%S "

setw -g window-status-format "#[fg=#475569,bg=#e2e8f0] #I:#W#F "
setw -g window-status-current-format "#[fg=#111827,bg=#facc15,bold] #I:#W#F "
setw -g window-status-style "fg=#475569,bg=#e2e8f0"
setw -g window-status-current-style "fg=#111827,bg=#facc15,bold"
setw -g window-status-bell-style "fg=#ffffff,bg=#dc2626,bold"

set -g window-style "fg=#64748b,bg=default,dim"
set -g window-active-style "fg=#111827,bg=default"
set -g pane-border-style "fg=#64748b,bg=default"
set -g pane-active-border-style "fg=#2563eb,bg=default"
setw -g clock-mode-colour "#2563eb"
setw -g mode-style "fg=#ffffff,bg=#2563eb,bold"
set -g message-style "fg=#111827,bg=#facc15,bold"
set -g message-command-style "fg=#ffffff,bg=#2563eb,bold"
EOF_KTS_2

cat > "$HOME/.config/tmux/themes/dark.tmux" <<'EOF_KTS_3'
# Dark theme with bright foregrounds and no dim attributes.

set -g status-style "fg=#f9fafb,bg=#111827,bold"
set -g status-left "#[fg=#111827,bg=#22d3ee,bold] #S #[fg=#22d3ee,bg=#111827,nobold] "
set -g status-right "#[fg=#f9fafb,bg=#111827,bold] CPU:#{cpu_percentage} #[fg=#94a3b8,bg=#111827,nobold]|#[fg=#f9fafb,bg=#111827,bold] Batt: #{battery_icon} #{battery_percentage} #{battery_remain} #[fg=#111827,bg=#a7f3d0,bold] %d/%m #[fg=#111827,bg=#f9a8d4,bold] %H:%M:%S "

setw -g window-status-format "#[fg=#cbd5e1,bg=#1f2937] #I:#W#F "
setw -g window-status-current-format "#[fg=#111827,bg=#22d3ee,bold] #I:#W#F "
setw -g window-status-style "fg=#cbd5e1,bg=#1f2937"
setw -g window-status-current-style "fg=#111827,bg=#22d3ee,bold"
setw -g window-status-bell-style "fg=#ffffff,bg=#ef4444,bold"

set -g window-style "fg=#475569,bg=default,dim"
set -g window-active-style "fg=#f9fafb,bg=default"
set -g pane-border-style "fg=#1f2937,bg=default"
set -g pane-active-border-style "fg=#22d3ee,bg=default"
setw -g clock-mode-colour "#22d3ee"
setw -g mode-style "fg=#111827,bg=#22d3ee,bold"
set -g message-style "fg=#111827,bg=#facc15,bold"
set -g message-command-style "fg=#111827,bg=#22d3ee,bold"
EOF_KTS_3

cat > "$HOME/.config/tmux/themes/dracula-local.tmux" <<'EOF_KTS_4'
# Dracula-inspired local theme. No plugin required.

set -g status-style "fg=#f8f8f2,bg=#282a36"

set -g status-left "#[fg=#bd93f9,bg=#282a36]#[fg=#282a36,bg=#bd93f9,bold] #{@karsin_tmux_icon_session} #S #[fg=#bd93f9,bg=#282a36] "
set -g status-right "#[fg=#a6e3a1,bg=#282a36]#[fg=#11111b,bg=#a6e3a1,bold] #{@karsin_tmux_icon_ram} #(~/.config/tmux/scripts/ram_percent.sh) #[fg=#a6e3a1,bg=#282a36] #[fg=#f9e2af,bg=#282a36]#[fg=#11111b,bg=#f9e2af,bold] #{@karsin_tmux_icon_cpu} #{cpu_percentage} #[fg=#f9e2af,bg=#282a36] #[fg=#ffb86c,bg=#282a36]#[fg=#11111b,bg=#ffb86c,bold] #{@karsin_tmux_icon_gpu} #(~/.config/tmux/scripts/gpu_percent.sh) #[fg=#ffb86c,bg=#282a36] #[fg=#cba6f7,bg=#282a36]#[fg=#11111b,bg=#cba6f7,bold] #{@karsin_tmux_icon_weather} #(~/.config/tmux/scripts/weather.sh #{@karsin_tmux_weather_location}) #{@karsin_tmux_icon_time} %H:%M #[fg=#cba6f7,bg=#282a36]"

if -F '#{==:#{@karsin_tmux_bar_style},online-rounded}' 'set -g status-left "#[fg=#bd93f9,bg=#282a36]#[fg=#282a36,bg=#bd93f9,bold] #{@karsin_tmux_icon_session} #S #[fg=#bd93f9,bg=#282a36] "; set -g status-right "#[fg=#a6e3a1,bg=#282a36]#[fg=#11111b,bg=#a6e3a1,bold] #{@karsin_tmux_icon_ram} #(~/.config/tmux/scripts/ram_percent.sh) #[fg=#a6e3a1,bg=#282a36] #[fg=#f9e2af,bg=#282a36]#[fg=#11111b,bg=#f9e2af,bold] #{@karsin_tmux_icon_cpu} #{cpu_percentage} #[fg=#f9e2af,bg=#282a36] #[fg=#ffb86c,bg=#282a36]#[fg=#11111b,bg=#ffb86c,bold] #{@karsin_tmux_icon_gpu} #(~/.config/tmux/scripts/gpu_percent.sh) #[fg=#ffb86c,bg=#282a36] #[fg=#cba6f7,bg=#282a36]#[fg=#11111b,bg=#cba6f7,bold] #{@karsin_tmux_icon_weather} #(~/.config/tmux/scripts/weather.sh #{@karsin_tmux_weather_location}) #{@karsin_tmux_icon_time} %H:%M #[fg=#cba6f7,bg=#282a36]"'
if -F '#{==:#{@karsin_tmux_bar_style},dracula-pro}' 'set -g status-left "#[fg=#282a36,bg=#bd93f9,bold] #{@karsin_tmux_icon_session} #S #[fg=#bd93f9,bg=#282a36,nobold]"; set -g status-right "#[fg=#6272a4,bg=#282a36]#[fg=#f8f8f2,bg=#6272a4] #{@karsin_tmux_icon_ram} #(~/.config/tmux/scripts/ram_percent.sh) #[fg=#44475a,bg=#6272a4]#[fg=#f8f8f2,bg=#44475a] #{@karsin_tmux_icon_cpu} #{cpu_percentage} #[fg=#ffb86c,bg=#44475a]#[fg=#282a36,bg=#ffb86c,bold] #{@karsin_tmux_icon_gpu} #(~/.config/tmux/scripts/gpu_percent.sh) #[fg=#bd93f9,bg=#ffb86c]#[fg=#282a36,bg=#bd93f9,bold] #{@karsin_tmux_icon_weather} #(~/.config/tmux/scripts/weather.sh #{@karsin_tmux_weather_location})  #{@karsin_tmux_icon_time} %H:%M "'
if -F '#{==:#{@karsin_tmux_bar_style},dracula-compact}' 'set -g status-left "#[fg=#282a36,bg=#bd93f9,bold] #{@karsin_tmux_icon_session} #S #[fg=#bd93f9,bg=#282a36]"; set -g status-right "#[fg=#44475a,bg=#282a36]#[fg=#f8f8f2,bg=#44475a] #{@karsin_tmux_icon_ram} #(~/.config/tmux/scripts/ram_percent.sh)  #{@karsin_tmux_icon_cpu} #{cpu_percentage}  #{@karsin_tmux_icon_gpu} #(~/.config/tmux/scripts/gpu_percent.sh)  #{@karsin_tmux_icon_weather} #(~/.config/tmux/scripts/weather.sh #{@karsin_tmux_weather_location}) #[fg=#bd93f9,bg=#44475a]#[fg=#282a36,bg=#bd93f9,bold] #{@karsin_tmux_icon_time} %H:%M "'
if -F '#{==:#{@karsin_tmux_bar_style},emoji-powerline}' 'set -g status-left "#[fg=#282a36,bg=#bd93f9,bold] #{@karsin_tmux_icon_session} #S #[fg=#bd93f9,bg=#44475a]"; set -g status-right "#[fg=#50fa7b,bg=#282a36]#[fg=#282a36,bg=#50fa7b,bold] #{@karsin_tmux_icon_ram} #(~/.config/tmux/scripts/ram_percent.sh) #[fg=#ffb86c,bg=#50fa7b]#[fg=#282a36,bg=#ffb86c,bold] #{@karsin_tmux_icon_cpu} #{cpu_percentage} #[fg=#ff79c6,bg=#ffb86c]#[fg=#282a36,bg=#ff79c6,bold] #{@karsin_tmux_icon_gpu} #(~/.config/tmux/scripts/gpu_percent.sh) #[fg=#bd93f9,bg=#ff79c6]#[fg=#282a36,bg=#bd93f9,bold] #{@karsin_tmux_icon_weather} #(~/.config/tmux/scripts/weather.sh #{@karsin_tmux_weather_location}) #{@karsin_tmux_icon_time} %H:%M "'
if -F '#{==:#{@karsin_tmux_bar_style},full}' 'set -g status-left "#[fg=#282a36,bg=#bd93f9,bold] #{@karsin_tmux_icon_session} #S #[fg=#bd93f9,bg=#282a36]"; set -g status-right "#[fg=#6272a4,bg=#282a36]#[fg=#f8f8f2,bg=#6272a4] #{@karsin_tmux_icon_ram} RAM #(~/.config/tmux/scripts/ram_percent.sh) #[fg=#44475a,bg=#6272a4]#[fg=#f8f8f2,bg=#44475a] #{@karsin_tmux_icon_cpu} CPU #{cpu_percentage} #[fg=#ffb86c,bg=#44475a]#[fg=#282a36,bg=#ffb86c,bold] #{@karsin_tmux_icon_gpu} GPU #(~/.config/tmux/scripts/gpu_percent.sh) #[fg=#bd93f9,bg=#ffb86c]#[fg=#282a36,bg=#bd93f9,bold] #{@karsin_tmux_icon_weather} #(~/.config/tmux/scripts/weather.sh #{@karsin_tmux_weather_location})  #{@karsin_tmux_icon_time} %a %d/%m %H:%M:%S "'
if -F '#{==:#{@karsin_tmux_bar_style},plain}' 'set -g status-left "#[fg=#bd93f9,bg=#282a36,bold] #{@karsin_tmux_icon_session} #S "; set -g status-right "#[fg=#f8f8f2,bg=#282a36] RAM #(~/.config/tmux/scripts/ram_percent.sh)  CPU #{cpu_percentage}  GPU #(~/.config/tmux/scripts/gpu_percent.sh)  WEATHER #(~/.config/tmux/scripts/weather.sh #{@karsin_tmux_weather_location})  %H:%M "'

setw -g window-status-format "#[fg=#6c7086,bg=#282a36] #I:#W#F "
setw -g window-status-current-format "#[fg=#282a36,bg=#cba6f7,bold] #I:#W#F "
setw -g window-status-style "fg=#6c7086,bg=#282a36"
setw -g window-status-current-style "fg=#282a36,bg=#cba6f7,bold"
setw -g window-status-bell-style "fg=#f8f8f2,bg=#ff5555,bold"

set -g window-style "fg=#4a4f66,bg=default,dim"
set -g window-active-style "fg=#f8f8f2,bg=default"
set -g pane-border-style "fg=#3a3f56,bg=default"
set -g pane-active-border-style "fg=#bd93f9,bg=default"
setw -g clock-mode-colour "#bd93f9"
